  "content": "import sqlite3
from flask import g, current_app
import re

DATABASE = 'talentfilter.db'

SCHEMA_SQL = """
CREATE TABLE IF NOT EXISTS job_openings (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    department TEXT NOT NULL,
    required_skills TEXT NOT NULL,
    min_experience_years REAL NOT NULL DEFAULT 0,
    status TEXT NOT NULL DEFAULT 'Open',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS candidates (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    job_opening_id INTEGER NOT NULL,
    full_name TEXT NOT NULL,
    email TEXT NOT NULL,
    phone TEXT,
    resume_url TEXT,
    skills_detected TEXT,
    experience_years REAL NOT NULL DEFAULT 0,
    match_score REAL NOT NULL DEFAULT 0,
    shortlist_status TEXT NOT NULL DEFAULT 'Applied',
    notes TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (job_opening_id) REFERENCES job_openings (id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS settings (
    key TEXT PRIMARY KEY,
    value TEXT NOT NULL
);
"""

def get_db():
    """Get request-scoped SQLite connection."""
    if 'db' not in g:
        db_path = current_app.config.get('DATABASE', DATABASE)
        g.db = sqlite3.connect(db_path, detect_types=sqlite3.PARSE_DECLTYPES)
        g.db.row_factory = sqlite3.Row
        g.db.execute("PRAGMA foreign_keys = ON;")
    return g.db

def close_db(e=None):
    """Close database connection on teardown."""
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    """Execute the initialization schema."""
    db = get_db()
    db.executescript(SCHEMA_SQL)
    db.commit()

def init_app(app):
    """Register DB hooks and initialize the schema."""
    app.teardown_appcontext(close_db)
    with app.app_context():
        init_db()

def row_to_dict(row):
    """Convert sqlite3.Row to standard dict."""
    if row is None:
        return None
    return {key: row[key] for key in row.keys()}

def calculate_match_score(required_skills_str, detected_skills_str, min_exp, candidate_exp):
    """
    Calculate a deterministic match score (0 to 100) based on:
    - Skills overlap (up to 70%)
    - Experience criteria (up to 30%)
    """
    try:
        min_exp = float(min_exp) if min_exp is not None else 0.0
    except (ValueError, TypeError):
        min_exp = 0.0

    try:
        candidate_exp = float(candidate_exp) if candidate_exp is not None else 0.0
    except (ValueError, TypeError):
        candidate_exp = 0.0

    def tokenize(s):
        if not s:
            return set()
        cleaned = re.sub(r'[,;/|]+', ' ', str(s).lower())
        return {token.strip() for token in cleaned.split() if len(token.strip()) > 1}

    req_tokens = tokenize(required_skills_str)
    cand_tokens = tokenize(detected_skills_str)

    skill_score = 70.0
    if req_tokens:
        matches = req_tokens.intersection(cand_tokens)
        skill_score = (len(matches) / len(req_tokens)) * 70.0

    exp_score = 30.0
    if min_exp > 0:
        ratio = candidate_exp / min_exp
        if ratio > 1.5:
            exp_score = 30.0
        else:
            exp_score = min(30.0, ratio * 30.0)

    total = round(skill_score + exp_score, 1)
    return min(100.0, max(0.0, total))
